<?php
$id=is_string($_GET['id']??null)?$_GET['id']:'0';$pc=Access::equipment($id);$student=Access::role()==='ALUMNO';
$extra=Access::role()==='DOCENTE'?' AND id_laboratorio_observado=?':'';$args=[$id];if($extra){$args[]=$pc['id_laboratorio'];}
$captures=query('SELECT id_registro,fecha,estado,hostname_reportado,sistema_operativo,cpu,ram_gb,ip FROM registro WHERE id_equipo=?'.$extra.' ORDER BY fecha DESC,id_registro DESC LIMIT '.($student?'1':'25'),$args)->fetchAll();
if($student){view('mi-equipo',['pc'=>$pc,'captures'=>$captures,'id'=>$id]);return;}
?>
<?php if(!$student): ?><a class="text-link back" href="<?= e(url('equipos')) ?>">← Volver al inventario</a><?php endif ?><div class="page-heading"><div><p class="eyebrow"><?= $student?'MI PC · DETECCIÓN POR IP':'FICHA DEL EQUIPO' ?></p><h1><?= e($pc['hostname']?:'PC #'.$pc['id_equipo']) ?></h1><p class="muted"><?= e($pc['laboratorio']??'Sin laboratorio asignado') ?></p></div><?php if(manage()): ?><a class="button secondary" href="<?= e(url('equipos',['edit'=>$id])) ?>#formulario">Editar PC</a><?php endif ?></div>
<section class="panel form-panel"><h2><?= $student?'Estado de mi PC':'Identidad y asignación' ?></h2><dl class="details"><?php foreach(($student?['laboratorio'=>'Laboratorio actual','estado_administrativo'=>'Estado administrativo']:['num_serie'=>'Número de serie','smbios_uuid'=>'UUID SMBIOS','laboratorio'=>'Laboratorio actual','estado_administrativo'=>'Estado administrativo']) as $key=>$label): ?><div><dt><?= e($label) ?></dt><dd><?= e($key==='estado_administrativo'?Inventory::STATES[$pc[$key]]:($pc[$key]?:'Sin informar')) ?></dd></div><?php endforeach ?></dl></section>
<section class="panel"><div class="panel-heading"><div><h2><?= $student?'Último diagnóstico':'Últimas capturas' ?></h2><p class="muted">Fechas expresadas en UTC.</p></div></div><?php if(!$captures): ?><div class="empty"><h3>Esta PC todavía no recibió capturas</h3></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Fecha (UTC)</th><th>Lectura</th><?php if(manage()): ?><th>Sistema operativo</th><th>CPU</th><th>RAM (GB)</th><th>IP</th><?php endif ?></tr></thead><tbody><?php foreach($captures as $capture): ?><tr><td><?= e($capture['fecha']) ?></td><td><span class="badge <?= $capture['estado']==='OK'?'good':'warn' ?>"><?= e($capture['estado']) ?></span></td><?php if(manage()): ?><td><?= e($capture['sistema_operativo']??'—') ?></td><td><?= e($capture['cpu']??'—') ?></td><td><?= e($capture['ram_gb']??'—') ?></td><td class="mono"><?= e($capture['ip']??'—') ?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<?php if(manage()||$student){view('comments',['kind'=>'equipo','id'=>$id]);}else{ ?><p class="info-strip">Podés comentar sobre la sala desde <a href="<?= e(url('laboratorio',['id'=>$pc['id_laboratorio']])) ?>">tu laboratorio asignado</a>.</p><?php } ?>

<?php view('reports',['id'=>$id]); ?>

<?php if(Access::role()!=='ALUMNO'): ?><p><a class="text-link" href="<?= e(url('historial',['equipo'=>$id])) ?>">Ver historial completo y exportar capturas de esta PC →</a></p><?php endif ?>
